const D = { energy: .6, swirl: .6, density: .55, speed: 1, dissipate: .38, scale: 1, hue: 300, x: .5, y: .6, style: 'ink', act: 'billow', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const clp = (v,a,b)=>Math.max(a,Math.min(b,v)), TAU=Math.PI*2;
const hsh = i=>{const s=Math.sin(i*127.1+(P.seed|0)*311.7)*43758.5453;return s-Math.floor(s);};
const hsb2rgb = (h,s,v)=>{h=((h%360)+360)%360;s=clp(s,0,1);v=clp(v,0,1);const c=v*s,xx=c*(1-Math.abs((h/60)%2-1)),m=v-c;let r,g,b;const k=Math.floor(h/60)%6;if(k===0){r=c;g=xx;b=0;}else if(k===1){r=xx;g=c;b=0;}else if(k===2){r=0;g=c;b=xx;}else if(k===3){r=0;g=xx;b=c;}else if(k===4){r=xx;g=0;b=c;}else{r=c;g=0;b=xx;}return[r+m,g+m,b+m];};
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

const W=width, H=height, md=Math.min(W,H);

// ---- coarse grid (long axis 72..132), size + seed keyed ----
const LA=Math.min(132, Math.round(82 + clp(P.density,0,1)*50));
const AR=W/H;
const GW=AR>=1?LA:Math.max(28,Math.round(LA*AR));
const GH=AR>=1?Math.max(28,Math.round(LA/AR)):LA;
if(!S.c0 || S.gw!==GW || S.gh!==GH || S.seedUsed!==(P.seed|0)){
  S.gw=GW; S.gh=GH; S.seedUsed=(P.seed|0);
  const N=GW*GH;
  S.c0=new Float32Array(N); S.c1=new Float32Array(N); S.c2=new Float32Array(N);
  S.t0=new Float32Array(N); S.t1=new Float32Array(N); S.t2=new Float32Array(N);
  S.vx=new Float32Array(N); S.vy=new Float32Array(N); S.psi=new Float32Array(N);
  S.noff=hsh(7)*1000;
  if(S.buf&&S.buf.remove)S.buf.remove();
  S.buf=createGraphics(GW,GH); S.buf.pixelDensity(1);
  // three soft offset colored blobs so frame 0 is never blank / mono
  for(let y=0;y<GH;y++)for(let x=0;x<GW;x++){
    const dx=x/GW-0.5, dy=y/GH-0.5, i=y*GW+x;
    S.c0[i]=Math.max(0, 0.5-2.6*((dx+0.13)*(dx+0.13)+(dy+0.02)*(dy+0.02)));
    S.c1[i]=Math.max(0, 0.5-2.6*((dx-0.13)*(dx-0.13)+(dy-0.06)*(dy-0.06)));
    S.c2[i]=Math.max(0, 0.5-2.6*(dx*dx+(dy+0.15)*(dy+0.15)));
  }
  S.pbeat=Math.floor(K.beat);
}
const GN=GW*GH, c0=S.c0,c1=S.c1,c2=S.c2, t0=S.t0,t1=S.t1,t2=S.t2, vx=S.vx,vy=S.vy,psi=S.psi, buf=S.buf;

// dt guard (tolerate t0 resets / backward jumps)
let dt=K.t-(S.lastT!=null?S.lastT:K.t); if(!(dt>0)||dt>0.4)dt=0.016; S.lastT=K.t;

// ---- 1. velocity = curl of a noise stream-function (divergence-free) ----
const zt=K.t*(0.05+P.speed*0.06)+S.noff;              // REAL-TIME evolution -> motion floor
const nsc=2.6/Math.max(0.4,P.scale);                  // vortex size
const vg=(7+clp(P.swirl,0,2)*22)*(0.75+K.intensity*0.55); // curl gain, breathes with section arc
for(let y=0;y<GH;y++)for(let x=0;x<GW;x++)
  psi[y*GW+x]=noise(x/GW*nsc+S.noff, y/GH*nsc, zt);
for(let y=0;y<GH;y++){
  const yp=Math.min(GH-1,y+1), ym=Math.max(0,y-1);
  for(let x=0;x<GW;x++){
    const xp=Math.min(GW-1,x+1), xm=Math.max(0,x-1), i=y*GW+x;
    vx[i]=(psi[yp*GW+x]-psi[ym*GW+x])*vg;             //  d(psi)/dy
    vy[i]=-(psi[y*GW+xp]-psi[y*GW+xm])*vg;            // -d(psi)/dx
  }
}
// act 'vortex': add solid-body rotation about the anchor (whirlpool)
if(P.act==='vortex'){
  const cx=P.x*GW, cy=P.y*GH, om=1.5+P.swirl*1.4;
  for(let y=0;y<GH;y++)for(let x=0;x<GW;x++){
    const i=y*GW+x, rx=x-cx, ry=y-cy, r=Math.hypot(rx,ry)+1e-3;
    vx[i]+=-ry/r*om; vy[i]+=rx/r*om;
  }
}

// ---- beat impulse: local velocity kick on downbeats (curl-noise + beat impulses) ----
const bf=Math.floor(K.beat);
const newBeat = bf!==S.pbeat;
if(newBeat) S.pbeat=bf;
const kick=K.pulse*0.6+A.bass*0.8;
if(newBeat && kick>0.05){
  const bx=Math.round((0.5+(P.x-0.5)*0.7)*GW), by=Math.round((0.5+(P.y-0.5)*0.7)*GH);
  const rr=2+Math.round(clp(P.density,0,1)*2);
  for(let dy=-rr;dy<=rr;dy++)for(let dx=-rr;dx<=rr;dx++){
    const gx=bx+dx, gy=by+dy; if(gx<0||gx>=GW||gy<0||gy>=GH)continue;
    const dd=dx*dx+dy*dy, fall=Math.max(0,1-dd/((rr+0.8)*(rr+0.8))), len=Math.sqrt(dd)+1e-3, i=gy*GW+gx;
    vx[i]+=dx/len*kick*2.8*fall; vy[i]+=(dy/len-0.5)*kick*2.8*fall;   // outward + slight lift
  }
}

// ---- 2. inject colorful pigment (perpetual -> coverage + luminance + motion floor) ----
const isBloom=(P.act==='bloom');
const bloomHit = isBloom && newBeat && (bf%2===0);
const nInj=Math.min(6, 3+Math.round(clp(P.density,0,1)*3));
const injF=0.5+A.bass*0.7+K.pulse*0.4;                // audio ON TOP of a clk baseline
const inten=0.75+K.intensity*0.5;
for(let q=0;q<nInj;q++){
  let amt;
  if(isBloom){ amt = bloomHit ? 0.95*inten*(0.6+P.energy*0.7) : (q===0?0.09*inten:0); }
  else { amt = 0.46*inten*(0.6+P.energy*0.7); }
  if(amt<=0) continue;
  const ang=K.t*(0.24+q*0.11)+q*2.399, rad=(P.act==='vortex'?0.06:0.26)+0.16*Math.sin(K.t*0.08+q*1.7);
  const ix=Math.round((0.5+(P.x-0.5)*0.65+Math.cos(ang)*rad)*GW);
  const iy=Math.round((0.5+(P.y-0.5)*0.65+Math.sin(ang)*rad)*GH);
  const rr=(bloomHit?4:1)+Math.round(clp(P.density,0,1)*2);
  const chan=q%3;
  for(let dy=-rr;dy<=rr;dy++)for(let dx=-rr;dx<=rr;dx++){
    const gx=ix+dx, gy=iy+dy; if(gx<0||gx>=GW||gy<0||gy>=GH)continue;
    const fall=Math.max(0,1-(dx*dx+dy*dy)/((rr+0.7)*(rr+0.7)));
    const i=gy*GW+gx, add=fall*injF*amt;
    if(chan===0)c0[i]=Math.min(1.35,c0[i]+add);
    else if(chan===1)c1[i]=Math.min(1.35,c1[i]+add);
    else c2[i]=Math.min(1.35,c2[i]+add);
    vy[i]-=1.0*injF*fall;                             // buoyant lift (plume rises)
    vx[i]+=dx*0.11;                                   // slight lateral spread
  }
}

// ---- 3. semi-Lagrangian advect all 3 channels (one backtrace, 3 samples) + dissipate ----
const flow=(0.55+P.speed*1.1);
const dissip=1-(0.006+clp(P.dissipate,0,1)*0.03);
for(let y=0;y<GH;y++)for(let x=0;x<GW;x++){
  const i=y*GW+x;
  let sx=x-vx[i]*flow, sy=y-vy[i]*flow;
  if(sx<0)sx=0; else if(sx>GW-1.001)sx=GW-1.001;
  if(sy<0)sy=0; else if(sy>GH-1.001)sy=GH-1.001;
  const x0=sx|0, y0=sy|0, fx=sx-x0, fy=sy-y0;
  const i00=y0*GW+x0, i10=i00+1, i01=i00+GW, i11=i01+1;
  const w00=(1-fx)*(1-fy), w10=fx*(1-fy), w01=(1-fx)*fy, w11=fx*fy;
  t0[i]=(c0[i00]*w00+c0[i10]*w10+c0[i01]*w01+c0[i11]*w11)*dissip;
  t1[i]=(c1[i00]*w00+c1[i10]*w10+c1[i01]*w01+c1[i11]*w11)*dissip;
  t2[i]=(c2[i00]*w00+c2[i10]*w10+c2[i01]*w01+c2[i11]*w11)*dissip;
}
// ---- 4. diffuse = one blur pass (implicit diffusion stand-in) -> back into c ----
const dif=0.13;
for(let y=0;y<GH;y++){
  const yp=Math.min(GH-1,y+1), ym=Math.max(0,y-1);
  for(let x=0;x<GW;x++){
    const xp=Math.min(GW-1,x+1), xm=Math.max(0,x-1), i=y*GW+x;
    const n0=(t0[ym*GW+x]+t0[yp*GW+x]+t0[y*GW+xm]+t0[y*GW+xp])*0.25;
    const n1=(t1[ym*GW+x]+t1[yp*GW+x]+t1[y*GW+xm]+t1[y*GW+xp])*0.25;
    const n2=(t2[ym*GW+x]+t2[yp*GW+x]+t2[y*GW+xm]+t2[y*GW+xp])*0.25;
    c0[i]=t0[i]*(1-dif)+n0*dif;
    c1[i]=t1[i]*(1-dif)+n1*dif;
    c2[i]=t2[i]*(1-dif)+n2*dif;
  }
}

// ---- 5. map pigment field -> colour -> coarse buffer -> upscale ----
const style=P.style, en=clp(P.energy,0,1);
const drift=K.section*14 + K.t*0.8;                    // palette drift across the arc
const hbase=((P.hue%360)+360)%360;
const pc0=hsb2rgb(hbase+drift, 0.92, 1.0);             // pigment triad (default -> magenta/yellow/cyan = CMY)
const pc1=hsb2rgb(hbase+120+drift, 0.92, 1.0);
const pc2=hsb2rgb(hbase+240+drift, 0.92, 1.0);
const iron=[[6,5,24],[64,14,120],[176,36,68],[240,120,22],[255,238,150]]; // thermal ironbow (0..255)

if(style==='blueprint'){
  // schematic: velocity vector grid + density iso-contour dots on dark navy (non-representational)
  const aMul=clp(P.alpha,0,100)/100;
  noStroke(); fill((hbase*0.15+215)%360, 55, 15, 100*aMul); rect(0,0,W,H); // dark navy ground
  const cw=W/GW, ch=H/GH, step=Math.max(4, Math.round(GW/28));
  // velocity vectors (sparse grid; bright cyan on navy)
  stroke(188, 55, 96, 65*aMul); strokeWeight(Math.max(1, md/950));
  for(let y=1;y<GH-1;y+=step)for(let x=1;x<GW-1;x+=step){
    const i=y*GW+x, px=(x+0.5)*cw, py=(y+0.5)*ch;
    const vl=Math.hypot(vx[i],vy[i])+1e-4, L=clp(vl*0.62,0.25,step*0.92)*cw;
    line(px,py, px+vx[i]/vl*L, py+vy[i]/vl*L);
  }
  // density iso-contour highlights (where total dye crosses a level band)
  noStroke();
  for(let y=0;y<GH;y+=3)for(let x=0;x<GW;x+=3){
    const i=y*GW+x, f=c0[i]+c1[i]+c2[i];
    if(f<0.14) continue;
    const band=Math.abs(((f*3)%1)-0.5);
    if(band<0.09){ fill(52, 78, 100, (55+K.swell*25)*aMul); circle((x+0.5)*cw,(y+0.5)*ch, md*0.004+1.5); }
  }
  drawingContext.shadowBlur=0; blendMode(BLEND);
} else {
  buf.loadPixels(); const pix=buf.pixels;
  for(let y=0;y<GH;y++)for(let x=0;x<GW;x++){
    const i=y*GW+x;
    const dxc=x/GW-0.5, dyc=y/GH-0.5, rc=dxc*dxc+dyc*dyc; // radial for gentle vignette/glow
    let r,g,b;
    if(style==='ink'){
      // saturated pigment blooming in water on a light ground — layered translucent inks (stays COLOURFUL, no CMY browning)
      const gcov=0.92+en*1.15;
      const a0=clp(c0[i]*gcov,0,0.96), a1=clp(c1[i]*gcov,0,0.96), a2=clp(c2[i]*gcov,0,0.96);
      const vig=1-0.14*rc*4;                            // soft vignette
      let rr0=0.86*vig, gg0=0.83*vig, bb0=0.80*vig;     // light paper-water ground (~0.82 lum)
      rr0=rr0*(1-a0)+pc0[0]*a0; gg0=gg0*(1-a0)+pc0[1]*a0; bb0=bb0*(1-a0)+pc0[2]*a0; // dye 0 over paper
      rr0=rr0*(1-a1)+pc1[0]*a1; gg0=gg0*(1-a1)+pc1[1]*a1; bb0=bb0*(1-a1)+pc1[2]*a1; // dye 1 over
      rr0=rr0*(1-a2)+pc2[0]*a2; gg0=gg0*(1-a2)+pc2[1]*a2; bb0=bb0*(1-a2)+pc2[2]*a2; // dye 2 over
      const pool=clp((a0+a1+a2)*0.5,0,0.55);            // ink pools deepen tonally (keeps colour)
      r=rr0*(1-pool*0.28); g=gg0*(1-pool*0.28); b=bb0*(1-pool*0.28);
    } else if(style==='smoke'){
      // luminous colored volumetric smoke on near-black (dark-key, additive)
      const gain=0.85+en*1.5, fl=0.045+0.05*Math.max(0,0.12-rc)*4;
      r=fl+(c0[i]*pc0[0]+c1[i]*pc1[0]+c2[i]*pc2[0])*gain;
      g=fl+(c0[i]*pc0[1]+c1[i]*pc1[1]+c2[i]*pc2[1])*gain;
      b=fl+(c0[i]*pc0[2]+c1[i]*pc1[2]+c2[i]*pc2[2])*gain;
    } else if(style==='thermal'){
      // ironbow schlieren false-colour of total density (non-representational)
      const f=clp((c0[i]+c1[i]+c2[i])*(0.5+en*0.95),0,1), ff=f*(iron.length-1);
      let si=Math.min(iron.length-2,ff|0); const tt=ff-si, a=iron[si], c=iron[si+1];
      r=(a[0]+(c[0]-a[0])*tt)/255; g=(a[1]+(c[1]-a[1])*tt)/255; b=(a[2]+(c[2]-a[2])*tt)/255;
    } else { // 'spectral' — hue from velocity direction, brightness from density (iridescent)
      const f=clp((c0[i]+c1[i]+c2[i])*(0.6+en*1.0),0,1);
      const dir=Math.atan2(vy[i],vx[i])/TAU*360;
      const cc=hsb2rgb(dir+hbase+drift*2, 0.82, clp(0.12+f*1.25,0,1));
      r=cc[0]; g=cc[1]; b=cc[2];
    }
    const p=i*4; pix[p]=clp(r,0,1)*255; pix[p+1]=clp(g,0,1)*255; pix[p+2]=clp(b,0,1)*255; pix[p+3]=255;
  }
  buf.updatePixels();
  drawingContext.imageSmoothingEnabled=true;            // bilinear upscale = smooth smoke
  noStroke();
  push();
  if(P.alpha<100) tint(0,0,100,clp(P.alpha,0,100));
  image(buf,0,0,W,H);
  pop();
  // gentle partial-frame beat breathe on dark styles (well under strobe cap; never on light ink)
  if(style!=='ink'){
    blendMode(ADD); noStroke();
    const bh=(style==='thermal')?32:(hbase+18);
    fill(bh, 45, 100, clp(5+7*K.swell+A.bass*9+A.treble*4, 0, 15)); rect(0,0,W,H);
    blendMode(BLEND);
  }
  drawingContext.shadowBlur=0; blendMode(BLEND);
}
